# Email Writing Exercise PDF - customer response email for Surge AI application
from reportlab.lib.pagesizes import letter
from reportlab.lib.units import inch
from reportlab.lib.styles import ParagraphStyle
from reportlab.lib.enums import TA_LEFT
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, HRFlowable
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.pdfbase.pdfmetrics import registerFontFamily

# ---- palette (auto-generated by pdf.py palette.generate, monochrome, seed 7) ----
from reportlab.lib import colors
ACCENT       = colors.HexColor('#348ebb')
TEXT_PRIMARY = colors.HexColor('#1b1a18')
TEXT_MUTED   = colors.HexColor('#848077')
BG_SURFACE   = colors.HexColor('#e2dfd8')

# ---- fonts (host: Windows) ----
pdfmetrics.registerFont(TTFont('Times New Roman', r'C:\Windows\Fonts\times.ttf'))
pdfmetrics.registerFont(TTFont('Times New Roman Bold', r'C:\Windows\Fonts\timesbd.ttf'))
pdfmetrics.registerFont(TTFont('Times New Roman Italic', r'C:\Windows\Fonts\timesi.ttf'))
pdfmetrics.registerFont(TTFont('Times New Roman BoldItalic', r'C:\Windows\Fonts\timesbi.ttf'))
registerFontFamily('Times New Roman', normal='Times New Roman',
                   bold='Times New Roman Bold', italic='Times New Roman Italic',
                   boldItalic='Times New Roman BoldItalic')

kicker_style = ParagraphStyle('Kicker', fontName='Times New Roman Bold', fontSize=9,
    leading=12, textColor=ACCENT, spaceAfter=2)
title_style = ParagraphStyle('Title', fontName='Times New Roman Bold', fontSize=15,
    leading=19, textColor=TEXT_PRIMARY, spaceAfter=6)
meta_style = ParagraphStyle('Meta', fontName='Times New Roman', fontSize=10,
    leading=14, textColor=TEXT_MUTED, spaceAfter=1)
body_style = ParagraphStyle('Body', fontName='Times New Roman', fontSize=10.5,
    leading=15.5, textColor=TEXT_PRIMARY, alignment=TA_LEFT, spaceAfter=9)
bullet_style = ParagraphStyle('Bullet', fontName='Times New Roman', fontSize=10.5,
    leading=15.5, textColor=TEXT_PRIMARY, leftIndent=18, bulletIndent=4, spaceAfter=6)
num_style = ParagraphStyle('Num', fontName='Times New Roman', fontSize=10.5,
    leading=15.5, textColor=TEXT_PRIMARY, leftIndent=18, firstLineIndent=-14, spaceAfter=6)
sig_style = ParagraphStyle('Sig', fontName='Times New Roman', fontSize=10.5,
    leading=15, textColor=TEXT_PRIMARY, spaceAfter=0)

hdr_label = ParagraphStyle('HdrLabel', fontName='Times New Roman Bold', fontSize=9.5,
    leading=13, textColor=TEXT_MUTED)
hdr_val = ParagraphStyle('HdrVal', fontName='Times New Roman', fontSize=9.5,
    leading=13, textColor=TEXT_PRIMARY)

doc = SimpleDocTemplate(
    r'C:\Users\Lenovo\Downloads\Abdulrahman_Bello_Email_Exercise.pdf', pagesize=letter,
    leftMargin=0.9*inch, rightMargin=0.9*inch, topMargin=0.75*inch, bottomMargin=0.75*inch,
    title='Email Writing Exercise - Abdulrahman Bello',
    author='Abdulrahman Bello', creator='Abdulrahman Bello',
    subject='Customer response email - factuality delivery quality review')

story = []

story.append(Paragraph('SURGE AI — EMAIL WRITING EXERCISE', kicker_style))
story.append(Paragraph('Response to Customer: Factuality Delivery Quality Review', title_style))
story.append(HRFlowable(width='100%', thickness=1.0, color=ACCENT, spaceBefore=2, spaceAfter=10))

hdr_rows = [
    [Paragraph('To:', hdr_label), Paragraph('Customer QA Lead', hdr_val)],
    [Paragraph('From:', hdr_label), Paragraph('Abdulrahman Bello', hdr_val)],
    [Paragraph('Subject:', hdr_label), Paragraph('<b>Re: Quality concerns in latest factuality delivery</b>', hdr_val)],
]
hdr_table = Table(hdr_rows, colWidths=[0.7*inch, 5.5*inch], hAlign='CENTER')
hdr_table.setStyle(TableStyle([
    ('VALIGN', (0,0), (-1,-1), 'TOP'),
    ('LEFTPADDING', (0,0), (-1,-1), 0),
    ('RIGHTPADDING', (0,0), (-1,-1), 6),
    ('TOPPADDING', (0,0), (-1,-1), 2),
    ('BOTTOMPADDING', (0,0), (-1,-1), 2),
]))
story.append(hdr_table)
story.append(HRFlowable(width='100%', thickness=0.6, color=BG_SURFACE, spaceBefore=6, spaceAfter=12))

story.append(Paragraph('Hi,', body_style))
story.append(Paragraph(
    'Thank you for the careful review and for flagging this so quickly — your team was right to raise it. '
    'We re-reviewed all five responses in the delivered set, item by item, with our senior QA leads. Here is what we found:', body_style))

story.append(Paragraph(
    '<b>Asbestos response</b> — contains a clear factual error (“asbestos is a synthetic substance”; '
    'it is a naturally occurring mineral). Our flag was correct, and your team’s read agrees.', bullet_style, bulletText='•'))
story.append(Paragraph(
    '<b>Evaporation response</b> — materially accurate. Our rater counted a simplification '
    '(“evaporation occurs… as long as the temperatures are above freezing”) as an inaccuracy. '
    'We agree this label was wrong, and we are correcting it.', bullet_style, bulletText='•'))
story.append(Paragraph(
    '<b>Beatles response</b> — one item we would ask your team to re-check together: the response lists '
    '“Imagine” among famous Beatles songs, but it is a John Lennon solo single released after the band’s '
    'breakup. If that does not meet your bar for a material inaccuracy, we will accept your adjudication and correct the label.',
    bullet_style, bulletText='•'))

story.append(Paragraph(
    'Regardless of how the third item is adjudicated, two of the five returned labels did not meet the quality bar we '
    'promised you, and that is on us. Three changes are already in motion for future deliveries:', body_style))

story.append(Paragraph(
    '<b>1.</b>  <b>Verified rationales</b> — every “Contains Inaccuracy” label must quote the exact '
    'inaccurate span and cite the correcting source, so each negative label is independently checkable.', num_style))
story.append(Paragraph(
    '<b>2.</b>  <b>Adjudication pass</b> — all negative labels now receive a second senior review before any '
    'delivery ships.', num_style))
story.append(Paragraph(
    '<b>3.</b>  <b>Calibration against your QA</b> — we will seed every batch with gold items drawn from your '
    'team’s adjudications and track per-rater agreement, with retraining triggered automatically.', num_style))

story.append(Paragraph(
    'On billing: we are crediting this delivery in full, and we will re-review the remainder of the batch at no charge. '
    'I would also welcome a short call this week to walk through the findings and confirm the process changes above work '
    'for your team.', body_style))

story.append(Paragraph('Thank you again for catching this — it made our process better.', body_style))

story.append(Paragraph('Best regards,', sig_style))
story.append(Spacer(1, 2))
story.append(Paragraph('<b>Abdulrahman Bello</b>', sig_style))

doc.build(story)
print('OK - email exercise PDF written')
